<?php
require_once __DIR__.'/includes/functions.php';$user=require_login();if($user['role_code']!=='lab'){http_response_code(403);exit('Pencetakan hasil hanya untuk petugas laboratorium.');}
$pid=(int)($_GET['patient_id']??0);$pdo=db();$q=$pdo->prepare('SELECT full_name,medical_record_no,birth_date FROM patients WHERE id=?');$q->execute([$pid]);$patient=$q->fetch();if(!$patient){http_response_code(404);exit('Pasien tidak ditemukan.');}
$q=$pdo->prepare("SELECT l.id,l.test_name,l.verified_at,o.order_no,v.full_name verifier FROM lab_orders l JOIN orders o ON o.id=l.order_id JOIN registrations r ON r.id=o.registration_id LEFT JOIN employees v ON v.id=l.verified_by WHERE r.patient_id=? AND l.status='Tervalidasi' ORDER BY l.verified_at DESC");$q->execute([$pid]);$orders=$q->fetchAll();?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Hasil Laboratorium - <?=e($patient['medical_record_no'])?></title><style>body{font:14px Arial,sans-serif;margin:38px;color:#182334}header{text-align:center;border-bottom:2px solid #0f766e;padding:14px}h2{margin:23px 0 8px}table{width:100%;border-collapse:collapse;margin:12px 0 25px}td,th{padding:9px;border:1px solid #d8dce3;text-align:left}th{background:#f2f5f7}.actions{margin:20px 0}@media print{.actions{display:none}}</style></head><body><header><h1>Rumah Sakit Permata Asri</h1><b>LEMBAR HASIL LABORATORIUM</b></header><p><b>Nama:</b> <?=e($patient['full_name'])?> &nbsp; <b>No. RM:</b> <?=e($patient['medical_record_no'])?> &nbsp; <b>Tanggal Lahir:</b> <?=e($patient['birth_date'])?></p><div class="actions"><button onclick="window.print()">Cetak / Simpan sebagai PDF</button></div><?php foreach($orders as $order):?><h2><?=e($order['test_name'])?></h2><p><?=e($order['order_no'])?> · Validasi: <?=e($order['verified_at'])?> · <?=e($order['verifier']??'-')?></p><table><thead><tr><th>Parameter</th><th>Hasil</th><th>Satuan</th><th>Nilai Rujukan</th></tr></thead><tbody><?php $v=$pdo->prepare('SELECT * FROM laboratory_values WHERE lab_order_id=? ORDER BY id');$v->execute([$order['id']]);foreach($v as $row):?><tr><td><?=e($row['parameter_name'])?></td><td><?=e($row['result_value'])?></td><td><?=e($row['result_unit'])?></td><td><?=e($row['reference_range'])?></td></tr><?php endforeach;?></tbody></table><?php endforeach;?><?php if(!$orders):?><p>Belum ada hasil yang tervalidasi.</p><?php endif;?><p style="font-size:11px;color:#64748b">Dokumen dihasilkan melalui SIMRS. Referensi pemeriksaan harus mengikuti laboratorium yang berlaku.</p></body></html>
